// bare-mypage-editorial-redesign-v1
const bareMyEditorialStyle='<style id="bare-my-editorial-style">body{background:#f3f3ef!important}.my-page{width:min(1320px,calc(100% - 48px))!important;padding:24px 0 100px!important}.my-head{display:flex!important;align-items:center!important;justify-content:space-between!important;height:56px!important;text-align:left!important}.my-head h1{font-size:16px!important;letter-spacing:-.04em!important}.shop-link{position:static!important;display:inline-flex!important;align-items:center!important;height:34px!important;padding:0 13px!important;border:1px solid #111!important}.admin-link{display:none!important}.bare-my-hero{position:relative;display:grid;align-content:end;min-height:360px;margin:14px 0 18px;padding:34px;background:#080808;color:#fff;overflow:hidden}.bare-my-hero:before{content:"BARE.";position:absolute;right:-18px;top:-38px;color:#181818;font:900 clamp(120px,22vw,300px)/1 InterDisplay,Arial,sans-serif;letter-spacing:-.1em}.bare-my-hero small,.bare-my-hero strong,.bare-my-hero span{position:relative;z-index:1}.bare-my-hero small{font:900 10px/1 InterDisplay,sans-serif;letter-spacing:.22em}.bare-my-hero strong{display:block;margin-top:14px;font:900 clamp(50px,8vw,112px)/.83 InterDisplay,Arial,sans-serif;letter-spacing:-.075em}.bare-my-hero span{margin-top:20px;color:#bdbdbd;font:800 13px/1.55 Pretendard,sans-serif}.my-nav{display:flex!important;gap:8px!important;margin:0 0 18px!important;padding:0!important;background:transparent!important;overflow:auto!important;scrollbar-width:none}.my-nav button{flex:0 0 auto!important;min-height:40px!important;padding:0 15px!important;border:1px solid #cfcfcf!important;background:#fff!important;font-size:11px!important}.my-nav button:after{content:" ↗"}.my-nav button+button:before{display:none!important}.summary-grid{grid-template-columns:1.45fr repeat(3,1fr)!important;gap:10px!important}.summary-card{position:relative!important;display:flex!important;align-items:flex-end!important;justify-content:space-between!important;min-height:190px!important;padding:22px!important;border:1px solid #111!important;background:#fff!important;text-align:left!important}.profile-card{display:grid!important;grid-template-columns:72px minmax(0,1fr)!important;align-items:end!important;background:#111!important;color:#fff!important}.profile-icon{width:72px!important;height:72px!important;background:#f2ff38!important;color:#111!important;font-size:34px!important}.profile-copy{margin:0!important;font-size:14px!important}.grade-link{grid-column:1/3!important;margin:14px 0 0!important;color:#aaa!important;font-size:10px!important}.stat-label{font-size:12px!important;letter-spacing:.02em!important}.stat-value{margin:0!important;font-size:48px!important;letter-spacing:-.07em!important}.summary-card:after{content:"VIEW";position:absolute;right:20px;top:20px;font:900 9px/1 InterDisplay,sans-serif;letter-spacing:.12em}.summary-card#coupon-card{background:#f2ff38!important;cursor:pointer!important}.coupon-wallet{margin-top:10px!important;padding:28px!important;background:#fff!important;border:1px solid #111!important}.coupon-wallet-head{margin-bottom:20px!important}.coupon-wallet-head h2{font-size:20px!important;letter-spacing:-.04em!important}.wallet-coupon{min-height:134px!important;border:0!important;background:#111!important}.status-card{margin-top:10px!important;padding:30px 26px!important;border:1px solid #111!important;background:#fff!important}.status-card h2{margin-bottom:28px!important;font-size:13px!important}.status-grid{position:relative;gap:0!important}.status-grid:before{content:"";position:absolute;left:10%;right:10%;top:32px;height:1px;background:#111}.status-item{position:relative;min-height:100px!important;border:0!important;background:transparent!important}.status-item strong{position:relative;padding-top:52px!important;font-size:12px!important}.status-item strong:before{content:"";position:absolute;left:50%;top:24px;width:15px;height:15px;border:3px solid #fff;border-radius:50%;background:#111;box-shadow:0 0 0 1px #111;transform:translateX(-50%)}.status-item span{margin-top:9px!important;font-size:22px!important}.status-item.last{align-content:center!important;text-align:center!important}.status-item.last span{font-size:11px!important}.recent,.member-details{margin-top:64px!important}.recent h2,.member-details h2{margin-bottom:14px!important;padding-bottom:14px!important;border-bottom:3px solid #111!important;font-size:22px!important;letter-spacing:-.04em!important}.order-list{border:0!important;display:grid!important;gap:8px!important}.empty-orders{min-height:180px!important;border:1px solid #ccc!important;background:#fff!important}.order-row{border:1px solid #d0d0d0!important;background:#fff!important;padding:14px!important}.order-row img{width:92px!important;height:112px!important}.member-box{border:1px solid #111!important;background:#fff!important}.logout{margin-top:10px!important;background:#f2ff38!important;color:#111!important}.pagination{display:none!important}@media(max-width:900px){.my-page{width:calc(100% - 24px)!important;padding-top:12px!important}.my-head{height:48px!important}.bare-my-hero{min-height:290px;margin-top:8px;padding:22px}.bare-my-hero strong{font-size:58px}.bare-my-hero span{font-size:11px}.summary-grid{grid-template-columns:1fr 1fr!important}.profile-card{grid-column:1/3!important;min-height:160px!important}.summary-card{min-height:130px!important;padding:16px!important}.summary-grid .summary-card:last-child{grid-column:auto!important}.stat-value{font-size:34px!important}.summary-card:after{right:14px;top:14px}.coupon-wallet{padding:18px!important}.status-card{padding:22px 12px!important}.status-grid{grid-template-columns:repeat(4,1fr)!important}.status-grid:before{left:10%;right:10%;top:24px}.status-item{min-height:88px!important;border:0!important}.status-item strong{padding-top:42px!important;font-size:9px!important}.status-item strong:before{top:17px;width:12px;height:12px}.status-item span{font-size:17px!important}.status-item.last{grid-column:1/5!important;display:flex!important;justify-content:center!important;gap:18px!important;min-height:40px!important;border-top:1px solid #ddd!important}.recent,.member-details{margin-top:44px!important}.order-row{grid-template-columns:72px 1fr!important}.order-row img{width:72px!important;height:88px!important}}</style>';
const bareMyEditorialHero='<section class="bare-my-hero" aria-label="회원 대시보드"><small>BAREDOT MEMBER SPACE</small><strong>YOUR<br>BARE SPACE</strong><span>주문부터 웰컴팩 쿠폰까지<br>나만의 BARE. 기록을 확인하세요.</span></section>';
const bareMyEditorialScript='<script id="bare-my-editorial-script">(()=>{const hero=document.querySelector(".bare-my-hero"),name=document.getElementById("member-name"),coupon=document.getElementById("coupon-card");function sync(){const value=name?.textContent?.trim();if(hero&&value&&value!=="회원")hero.querySelector("span").innerHTML=value+"님의 주문부터 웰컴팩 쿠폰까지<br>나만의 BARE. 기록을 확인하세요."}new MutationObserver(sync).observe(document.body,{childList:true,subtree:true,characterData:true});coupon?.addEventListener("click",()=>document.getElementById("coupon-wallet")?.scrollIntoView({behavior:"smooth",block:"start"}));sync()})();</script>';
const bareMyEditorialBase=myPage;
myPage=function(){return bareMyEditorialBase().replace('</head>',bareMyEditorialStyle+'</head>').replace('</header><nav class="my-nav"','</header>'+bareMyEditorialHero+'<nav class="my-nav"').replace('</body>',bareMyEditorialScript+'</body>')};
